def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_n_pow_12(n, factors_n):
    if n == 1:
        return 1

    # n = p1^e1 * p2^e2 * ...
    # n^12 = p1^(12*e1) * p2^(12*e2) * ...
    # tau(n^12) = (12*e1 + 1) * (12*e2 + 1) * ...

    tau = 1
    for exponent in factors_n.values():
        tau *= (12 * exponent + 1)
    return tau

solutions = []
for n in range(1, 51):
    if n == 1:
        # Special case n=1
        if 1 == 1:
            solutions.append(n)
        continue

    factors = prime_factorization(n)
    tau_val = tau_n_pow_12(n, factors)

    if n == tau_val:
        solutions.append(n)

print("Solutions found for 1 <= n <= 50:", solutions)

# Check some specific cases manually for verification/patterns
# n=2: 2^1. tau(2^12) = 12*1 + 1 = 13. 2 != 13.
# n=3: 3^1. tau(3^12) = 13. 3 != 13.
# n=4: 2^2. tau((2^2)^12) = tau(2^24) = 12*2 + 1 = 25. 4 != 25.
# n=6: 2^1 * 3^1. tau(6^12) = (12*1 + 1)(12*1 + 1) = 13 * 13 = 169. 6 != 169.
# n=12: 2^2 * 3^1. tau(12^12) = (12*2 + 1)(12*1 + 1) = 25 * 13 = 325. 12 != 325.
# n=25: 5^2. tau((5^2)^12) = tau(5^24) = 12*2 + 1 = 25. 25 = 25. Solution!

for n in range(1, 51):
    factors = prime_factorization(n)
    tau_val = tau_n_pow_12(n, factors)
    if n != tau_val:
        pass # Just checking the logic flow
    else:
        print(f"n={n}, factors={factors}, tau(n^12)={tau_val}")

